import { GalleryVerticalEnd, ImageIcon, Video } from 'lucide-react';

import { AdminMetric, AdminPage, AdminPageHeader } from '@/features/admin/components';
import { MediaStudioDashboard } from '@/features/admin/media';
import { getVendorAccess } from '@/features/vendor/auth/vendorAccess';
import { cloudinaryIsConfigured } from '@/lib/cloudinary';
import { prisma } from '@/lib/prisma';

export default async function VendorMediaPage(){const access=await getVendorAccess();if(!access.permissions.has('media:view'))throw new Error('Media access is required.');const assets=await prisma.mediaAsset.findMany({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:'ACTIVE'},include:{uploadedBy:{select:{name:true}},vendorProfile:{select:{name:true}},_count:{select:{productImages:true,productVariants:true,promotionBanners:true,collectionCovers:true,storeStudioPrimaryAssets:true,storeStudioMobileAssets:true,storeStudioCoverAssets:true,storeStudioPosterAssets:true,vendorLogos:true}}},orderBy:{createdAt:'desc'},take:250});const mapped=assets.map(asset=>({...asset,createdAt:asset.createdAt.toISOString(),usageCount:Object.values(asset._count).reduce((sum,count)=>sum+count,0)}));return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow="Shared upload foundation" title="Vendor Media Studio" description="Upload directly to Cloudinary and reuse assets across your products, collections, promotions, Stories and Reels."/><section className="grid gap-3 sm:grid-cols-3"><AdminMetric icon={GalleryVerticalEnd} label="Assets" value={assets.length}/><AdminMetric icon={ImageIcon} label="Images" value={assets.filter(item=>item.resourceType==='IMAGE').length}/><AdminMetric icon={Video} label="Videos" value={assets.filter(item=>item.resourceType==='VIDEO').length}/></section><MediaStudioDashboard assets={mapped} canUpload={access.permissions.has('media:manage')} canDelete={access.permissions.has('media:manage')} configured={cloudinaryIsConfigured()} apiBasePath="/api/vendor/media"/></div></AdminPage>}
